    "kind": "day-trip",
    "direction": "from-city",
    "originCitySlug": "seville",
    "slugEn": "seville-to-jerez-day-trip",
    "slugEs": "sevilla-a-jerez-excursion-de-un-dia",
    "originNameEn": "Seville",
    "originNameEs": "Sevilla",
